# SPDX-License-Identifier: Apache-2.0
"""Advance the build number before packaging and record it in editor/midgard_editor/version.py.

Edit VERSION (major.minor.patch) by hand. Each build increments BUILD; it resets to 1 whenever the
major or minor version in VERSION changes. See the About Scheme (midgard_roadmap.md §12).
"""
import datetime
import re
import sys
from pathlib import Path

DIR = Path(__file__).resolve().parent
VERSION_FILE = DIR / "VERSION"
OUT = DIR / "editor" / "midgard_editor" / "version.py"

HEADER = (
    "# SPDX-License-Identifier: Apache-2.0\n"
    '"""Generated by bump_build.py during tools/package.py; edit VERSION instead."""\n'
)


def bump(version_file: Path = VERSION_FILE, out: Path = OUT,
         today: datetime.date | None = None) -> tuple[str, int, str]:
    version = version_file.read_text(encoding="utf-8").strip()
    if not re.fullmatch(r"\d+\.\d+\.\d+", version):
        sys.exit(f"VERSION must look like 1.2.3, not {version!r}")

    old_version, build = "", 0
    if out.exists():
        text = out.read_text(encoding="utf-8")
        if m := re.search(r'^VERSION = "([^"]*)"', text, re.M):
            old_version = m.group(1)
        if m := re.search(r"^BUILD = (\d+)", text, re.M):
            build = int(m.group(1))

    same_minor = old_version.split(".")[:2] == version.split(".")[:2]
    build = build + 1 if same_minor else 1
    date = (today or datetime.date.today()).isoformat()

    out.write_text(
        HEADER
        + f'VERSION = "{version}"\n'
        + f"BUILD = {build}\n"
        + f'BUILD_DATE = "{date}"  # ISO date of the build\n',
        encoding="utf-8")
    return version, build, date


def main() -> None:
    version, build, date = bump()
    print(f"Version {version} build {build} ({date})")


if __name__ == "__main__":
    main()
